#!/usr/bin/env bash
set -euo pipefail; M="${M:-16}"; H="${H:-16}"; ROUNDS="${ROUNDS:-200}"; DV="${DV:-1}"; POW2="${POW2:-1}"; PROGRESS="${PROGRESS:-1}"; BIN="${BIN:-build/oc_singlecol}"; T_LIST=(18 20 22 24 26 28 30 32 34 36 38 40); mkdir -p logs; if [[ ! -x "${BIN}" ]]; then echo "[INFO] ${BIN} not found. Building..."; make -j; fi; echo "[INFO] Generating unit weight files..."; rm -f wH_unit.txt wV_unit.txt; for((i=0;i<M;i++)); do for((j=0;j<H-1;j++)); do printf "1 "; done; echo; done > wH_unit.txt; for((i=0;i<M-1;i++)); do for((j=0;j<H;j++)); do printf "1 "; done; echo; done > wV_unit.txt; tr -d '\r' < wH_unit.txt > wH_unit.tmp && mv wH_unit.tmp wH_unit.txt; tr -d '\r' < wV_unit.txt > wV_unit.tmp && mv wV_unit.tmp wV_unit.txt; echo "[INFO] Unit weight files ready."; SUMMARY="summary_16x16.txt"; echo "T  HPWL_eq  maxL  Meet_MaxT" > "${SUMMARY}"; for T in "${T_LIST[@]}"; do echo "========== Run T=${T} (m=${M},h=${H},rounds=${ROUNDS},dV=${DV}) =========="; LOG="logs/singlecol_16x16_T_${T}.log"; ( set -x; time "${BIN}" "${M}" "${H}" --rounds="${ROUNDS}" --dV="${DV}" --T="${T}" --pow2="${POW2}" --progress="${PROGRESS}" --wH wH_unit.txt --wV wV_unit.txt ) 2>&1 | tee "${LOG}"; OUT="placement${M}_Col_1_T_${T}.txt"; [[ -f "${OUT}" ]] && echo "[OK] Generated: ${OUT}" || echo "[WARN] Output not found: ${OUT} (check ${LOG})"; HPWL=$(grep "HPWL_eq=" "${LOG}" | tail -n1 | sed -E 's/.*HPWL_eq=([0-9]+).*/\1/'); MAXL=$(grep "maxL=" "${LOG}" | tail -n1 | sed -E 's/.*maxL=([0-9]+).*/\1/'); if [[ -z "${HPWL}" ]]; then HPWL="NA"; fi; if [[ -z "${MAXL}" ]]; then MAXL="NA"; fi; MEET="NA"; if [[ "${MAXL}" != "NA" ]]; then (( MAXL<=T )) && MEET="YES" || MEET="NO"; fi; printf "%-4s %-8s %-6s %-4s\n" "${T}" "${HPWL}" "${MAXL}" "${MEET}" >> "${SUMMARY}"; done; echo "[DONE] All T finished. Summary saved to ${SUMMARY} (and logs/)"
